// GENERATED by scripts/sync-engine.js from src/engine/dose-filter.ts. Do not edit here; run `npm run sync-engine`.
/**
 * Dose filter for AI free text (pure). The AI must never give treatments: any text that
 * looks like an amount + unit, a rate ("per acre"), or names a spray / product /
 * chemical is replaced by "See advice below" (the official knowledge-base advice).
 * Every AI string is also trimmed and length-capped.
 */

export const REPLACEMENT = 'See advice below';
export const MAX_AI_TEXT = 300;

/** amount + unit: "250 ml", "2.5kg", "1 litre", "20 g", "0.1%", "500 ppm", "2 bags"… */
const AMOUNT_UNIT =
  /\b\d+(?:[.,]\d+)?\s*(?:-|to|–)?\s*\d*(?:[.,]\d+)?\s*(?:ml|millilit(?:er|re)s?|l|lit(?:er|re)s?|ltr|g|gm|gms|grams?|kg|kilos?|kilograms?|mg|oz|ounces?|%|percent|ppm|cc|tablets?|sachets?|packets?|bags?|bottles?|tola|maunds?|mann)\b|\d+(?:[.,]\d+)?\s*%/i;

/** rates: "per acre", "/acre", "per kanal", "per hectare", "per litre of water" */
const RATE = /\b(?:per|\/)\s*(?:acre|kanal|hectare|ha|litre|liter|l|gallon|tank|knapsack|plant)\b|\bper\s+\d/i;

/** treatment words and common active ingredients / product types */
const CHEMICAL = new RegExp(
  '\\b(?:' +
    [
      'spray(?:s|ing|ed)?',
      'fungicides?',
      'insecticides?',
      'pesticides?',
      'bactericides?',
      'herbicides?',
      'weedicides?',
      'acaricides?',
      'chemicals?',
      'dose|dosage',
      'drench(?:ing)?',
      'seed treatment',
      // common active ingredients (not exhaustive; the amount/rate rules catch the rest)
      'imidacloprid',
      'acetamiprid',
      'thiamethoxam',
      'dinotefuran',
      'flonicamid',
      'pyriproxyfen',
      'buprofezin',
      'diafenthiuron',
      'spirotetramat',
      'chlorpyrifos',
      'cypermethrin',
      'lambda[- ]?cyhalothrin',
      'bifenthrin',
      'deltamethrin',
      'emamectin',
      'abamectin',
      'chlorantraniliprole',
      'spinetoram',
      'lufenuron',
      'mancozeb',
      'copper(?: oxychloride| hydroxide| sulphate| sulfate)?',
      'carbendazim',
      'thiophanate',
      'tebuconazole',
      'propiconazole',
      'hexaconazole',
      'difenoconazole',
      'azoxystrobin',
      'trifloxystrobin',
      'pyraclostrobin',
      'tricyclazole',
      'isoprothiolane',
      'kasugamycin',
      'streptomycin',
      'validamycin',
      'sulphur|sulfur',
      'glyphosate',
      'urea',
      'dap',
    ].join('|') +
    ')\\b',
  'i',
);

/** Spelled-out amounts: "two litres", "half a bottle", "one and a half kg". */
const WORD_AMOUNT =
  /\b(?:one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|half|quarter|dozen)\b(?:\s+(?:and|a|an|of))*\s+(?:ml|millilit(?:er|re)s?|lit(?:er|re)s?|ltr|grams?|kg|kilos?|kilograms?|ounces?|percent|tablets?|sachets?|packets?|bags?|bottles?|tola|maunds?|mann|spoons?|teaspoons?|tablespoons?|cups?|caps?|capfuls?)\b/i;

/**
 * Text we ask for is simple English. Anything in another script (Urdu, Arabic, Hindi,
 * Punjabi…) can't be checked by the English rules, so it is never shown as AI text.
 * Allowed: Latin letters, digits, common punctuation and symbols.
 */
const NON_LATIN = /[^\u0000-\u024F\u1E00-\u1EFF\u2000-\u206F\u20A0-\u20CF\u2100-\u214F\u2190-\u21FF]/;
/** Invisible characters that could split a word ("spr\u200bay") to slip past the rules. */
const INVISIBLE = /[\u00AD\u034F\u061C\u115F\u1160\u17B4\u17B5\u180E\u200B-\u200F\u202A-\u202E\u2060-\u2064\u2066-\u206F\uFEFF]/g;

export function looksLikeTreatment(text: string): boolean {
  return AMOUNT_UNIT.test(text) || RATE.test(text) || CHEMICAL.test(text) || WORD_AMOUNT.test(text) || NON_LATIN.test(text);
}

/** Trim, cap and filter one AI string. Empty/missing → null. */
export function filterAiText(text: unknown, max = MAX_AI_TEXT): string | null {
  if (typeof text !== 'string') return null;
  // NFKC turns full-width / styled letters and digits ("２５０ｍｌ", "𝐬𝐩𝐫𝐚𝐲") into plain ones.
  const t = text.normalize('NFKC').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
  if (!t) return null;
  if (looksLikeTreatment(t)) return REPLACEMENT;
  return t.length > max ? `${t.slice(0, max - 1).trimEnd()}…` : t;
}

/** Filter a list: drop empties, cap count, collapse repeated "See advice below". */
export function filterAiList(items: unknown, maxItems = 5, maxLen = MAX_AI_TEXT): string[] {
  if (!Array.isArray(items)) return [];
  const out: string[] = [];
  for (const item of items) {
    const f = filterAiText(item, maxLen);
    if (!f || (f === REPLACEMENT && out.includes(REPLACEMENT))) continue;
    out.push(f);
    if (out.length >= maxItems) break;
  }
  return out;
}
